class string_buf;

class stringx
{
protected:
  char *chars;
  string_buf *my_buf;

public:
  stringx(const char *str, int len = -1);
  ~stringx();
  stringx &operator=(const stringx &cp);
  stringx &operator+=(const char *str);
  void to_upper();
  inline const char *c_str() const { return chars; }

  friend stringx operator+(const stringx& lhs, const stringx& rhs);
};

template <class T>
class singleton_ptr
{
  T* p;
public:
  operator T*() const { return p; }
};

class singleton
{
protected:
  singleton() {}
  virtual ~singleton() {}
};

class os_developer_options : public singleton
{
public:
  enum flags_t
  {
    FLAG_STASH_ONLY,
    FLAG_NO_CD
  };

  bool is_flagged(flags_t flag) const { return flags[flag]; }
  static os_developer_options* inst() { return instance; }

private:
  static singleton_ptr<os_developer_options> instance;
  bool flags[2];
};

extern const char* nglHostPrefix;
extern "C" int sceSifLoadModule(char *, int, const char *);
void nglPrintf(const char *, ...);

bool load_iop_module(const char *module_name, const char *debug_path)
{
  int ret = -1;

  // try to grab the sio2man off of the CD first 
  if (!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_CD))
  {
    stringx cd_name(module_name);
    cd_name.to_upper();
    cd_name = stringx("cdrom0:\\") + cd_name;
    cd_name += ";1";
nglPrintf("Trying to open %s\n", cd_name.c_str());
    ret = sceSifLoadModule((char *)cd_name.c_str(), 0, 0);
  }

  if (ret < 0)
  {
    stringx disk_name(nglHostPrefix);
    disk_name += module_name;
    ret = sceSifLoadModule((char *)disk_name.c_str(), 0, 0);
  }

#if 0
  if (ret < 0 && os_developer_options::inst()->is_flagged(os_developer_options::FLAG_STASH_ONLY))
    return false;

  if (ret < 0)
  {
    stringx debug_name(debug_path);
    debug_name += module_name;
    ret = sceSifLoadModule((char *)debug_name.c_str(),0, 0);
  }
#endif
  return (ret >= 0);
}
